scwin.fn_SetComboCode = function() {
    cmb_SME_YN.CBData = scwin.strCbd_SME_YN;
    cmb_HDCOM_YN.CBData = scwin.strCbd_HDCOM_YN;
    cmb_SME_YN.setSelectedIndex(0);
    cmb_HDCOM_YN.setSelectedIndex(0);

    //주거래은행
    dts_MaintrBkCd.DataID = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listInstCd&For=";
    dts_MaintrBkCd.Reset();
    $c.elw.fn_searchCode();
};
scwin.fn_searchCode = function() {
    /*
    00443-통화ISO코드-일반사항-CURR_ISO_CD-cmb_CurrIsoCd
    00443-액면가통화ISO코드-일반사항-PARVAL_CURR_ISO_CD-cmb_ParvalCurrIsoCd
    00443-재무통화ISO코드-일반사항-FNC_CURR_ISO_CD-cmb_CapCurrIsoCd
    00443-공모가통화ISO코드-일반사항-PUBPRC_CURR_ISO_CD-cmb_PubprcCurrIsoCd
    00443-공모가예정통화ISO코드-일반사항-PUBPRC_SCHDL_CURR_ISO_CD-cmb_PubprcSchdlCurrIsoCd
    00685-명의개서대행기관-일반사항-TRANSSTK_AGNT_CD-cmb_TransstkAgntCd
    00755 - 외부감사인코드
    */
    var arrCid = [{
        cid: "CURR_ISO_CD",
        cnm: "cmb_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PARVAL_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_FNC_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PUBPRC_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PUBPRC_SCHDL_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_NETINCM_CURR_ISO_CD"
    }, {
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "EXT_AUDTR_CD",
        cnm: "cmb_EXT_AUDTR_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='CURR_ISO_CD','TRANSSTK_AGNT_CD','EXT_AUDTR_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_COM_NM.src = "../img/btn_search.gif";
        img_COM_NM.setDisabled(false);
    } else if (initTyp == "X") {
        img_COM_NM.src = "../img/btn_search_d.gif";
        img_COM_NM.setDisabled(true);
    }
};
scwin.fn_initLabel = function(secugrpId) {
    //alert("secugrpId:"+secugrpId);
    lb_LIST_SHRS.setValue("*상장(예정)주식수");
    lb_PARVAL.setValue("액면가");
    lb_PUBOFR_SHRS.setValue("공모주식수");
    $c.stf.showObj(label_59, false);
    $c.stf.showObj(label_78, false);
    $c.stf.showObj(label_79, false);
    $c.stf.showObj(label_81, false);
    $c.stf.showObj(edt_NETINCM_AMT1, false);
    $c.stf.showObj(cmb_NETINCM_CURR_ISO_CD, false);
    if (secugrpId == "FS") {
        $c.libRoundPanel.PanelToGroupBox(panel_Forn_Item);
        $c.stf.showObj(label_47, false);
        $c.stf.showObj(label_80, false);
        $c.stf.showObj(label_78, true);
        $c.stf.showObj(label_79, true);
        $c.stf.showObj(label_81, true);
        $c.stf.showObj(label_dr, true);
        $c.stf.showObj(edt_NETINCM_AMT1, true);
        $c.stf.showObj(cmb_NETINCM_CURR_ISO_CD, true);
        $c.stf.showObj(panel_Forn_Item, true);
        $c.stf.showObj(cmb_CURR_ISO_CD, false);
        edt_PER1DR_FORNSTK_RTO.setDisabled(true);
        if ($c.stf.getObjectValue(cmb_PUBPRC_CURR_ISO_CD) == "") {
            $c.stf.setObjectValue(cmb_PUBPRC_CURR_ISO_CD, "KRW");
        }
        if ($c.stf.getObjectValue(cmb_PUBPRC_SCHDL_CURR_ISO_CD) == "") {
            $c.stf.setObjectValue(cmb_PUBPRC_SCHDL_CURR_ISO_CD, "KRW");
        }
    } else if (secugrpId == "DR") {
        $c.libRoundPanel.PanelToGroupBox(panel_Forn_Item);
        $c.stf.showObj(label_74, false);
        $c.stf.showObj(label_75, false);
        $c.stf.showObj(label_76, false);
        $c.stf.showObj(label_77, false);
        $c.stf.showObj(label_59, true);
        $c.stf.showObj(label_dr, true);
        $c.stf.showObj(cmb_PARVAL_CURR_ISO_CD, false);
        $c.stf.showObj(cmb_FNC_CURR_ISO_CD, false);
        $c.stf.showObj(cmb_PUBPRC_CURR_ISO_CD, false);
        $c.stf.showObj(cmb_PUBPRC_SCHDL_CURR_ISO_CD, false);
        $c.stf.showObj(cmb_NETINCM_CURR_ISO_CD, false);
        $c.stf.showObj(panel_Forn_Item, true);
        edt_PER1DR_FORNSTK_RTO.setDisabled(false);
        lb_LIST_SHRS.setValue("*상장DR수");
        lb_PARVAL.setValue("액면가(원주기준)");
        lb_PUBOFR_SHRS.setValue("공모DR수");
    } else {
        $c.stf.showObj(label_dr, false);
        $c.stf.showObj(panel_Forn_Item, false);
    }
    edt_LISTDD_CLSPRC.setValue("0");
    edt_FST_BAS_PRC.setValue("0");
};
scwin.fn_GetParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_STD_IND_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_STD_IND_NM); // 명칭값을 포함할 컨트롤

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
