    	txb_STD_IND_CD.value = arrPar[0].KOSDAQ_STD_IND_CD;
    }
    */
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    arrPar[3] = scwin.mktTpCd;
    arrPar[4] = SEARCH_TYP_SEC; //신규등록시
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        txb_COM_ENG_NM.setValue(arrPar[0].COM_ENG_NM);
        txb_CNTR_ISO_CD.alue = arrPar[0].CNTR_ISO_CD;
        txb_CNTR_ISO_NM.alue = arrPar[0].CNTR_ISO_NM;
        txb_HPAGE.setValue(arrPar[0].HPAGE);
        if ($c.stf.getObjectValue(txb_ISUR_CD) != "") {
            var url = "/Prelisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readNewRegPrelisting&inputMessageId=FIAS_PREEXAM_OUT" + "&ISUR_CD=" + txb_ISUR_CD.getValue();
            dts_Fias.DataID = encodeURI(url);
            dts_Fias.Reset();
        }
    }
};
scwin.fn_read_sync = function() {
    //alert("LST_LM_CD :"+LST_LM_CD);
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    var url = "/Prelisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readPrelisting&inputMessageId=PREEXAM_SEARCH_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_changeForm(dts_Item.getCellData(1, "INVSTG_PROG_STAT_CD"));
};
scwin.strCbd_INVSTG_PROG_STAT_CD_1 = "01^심사진행,02^심사완료,03^심사완료(6개월경과등),04^심사연기,05^심사철회,06^심사기각";
scwin.strCbd_INVSTG_PROG_STAT_CD_2 = "10^신규상장 - 비상장,11^신규상장 - 코스닥법인,21^재상장 - 인적분할,22^재상장 - 폐지,23^재상장 - 합병,24^재상장 - 물적분할";
scwin.fn_changeForm = function(gStatCd) {
    //alert("[gStatCd]:"+gStatCd);
    //alert("[gStatCd.charAt(0) ]:"+gStatCd.charAt(0) );
    if (gStatCd != "" && gStatCd.charAt(0) != '0') {
        //cmb_INVSTG_PROG_STAT_CD.Enable2 = false;
        cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
        cmb_INVSTG_PROG_STAT_CD.CBData = scwin.strCbd_INVSTG_PROG_STAT_CD_2;
    } else {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
        cmb_INVSTG_PROG_STAT_CD.CBData = scwin.strCbd_INVSTG_PROG_STAT_CD_1;
    }
    cmb_INVSTG_PROG_STAT_CD.BindColVal = gStatCd;
};
scwin.fn_getLeadComNoStr = function() {
    return dts_Item.getCellData(1, "LEADCOM_MBR_NM_STR");
};
scwin.fn_setLeadComNMStr = function(str_no, str_nm) {
    dts_Item.setCellData(1, "LEADCOM_MBR_NO_STR", str_no);
    dts_Item.setCellData(1, "LEADCOM_MBR_NM_STR", str_nm);
    txb_LEADCOM_MBR_NM_STR.setValue(str_nm);
    //alert("[str_no] :"+str_no);

};
